import{_ as n,a as o,c as s,ac as a}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 全册短语与句型 · 第49–60课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第三册：培养技能 · 全册短语与句型 · 第49–60课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-3/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-3/phrases-part-02"},"next":{"text":"第三册：培养技能 · 全册易错点","link":"/life/english/new-concept/book-3/mistakes"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-3/phrases-part-02"},"next":{"text":"第三册：培养技能 · 全册易错点","link":"/life/english/new-concept/book-3/mistakes"}},"headers":[],"relativePath":"life/english/new-concept/book-3/phrases-part-03.md","filePath":"life/english/new-concept/book-3/phrases-part-03.md"}'),l={name:"life/english/new-concept/book-3/phrases-part-03.md"};function i(t,e,r,h,p,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="第三册-培养技能-·-全册短语与句型-·-第49–60课" tabindex="-1">第三册：培养技能 · 全册短语与句型 · 第49–60课 <a class="header-anchor" href="#第三册-培养技能-·-全册短语与句型-·-第49–60课" aria-label="Permalink to &quot;第三册：培养技能 · 全册短语与句型 · 第49–60课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="lesson-49-·-介词加关系代词" tabindex="-1">Lesson 49 · 介词加关系代词 <a class="header-anchor" href="#lesson-49-·-介词加关系代词" aria-label="Permalink to &quot;Lesson 49 · 介词加关系代词 {#lesson-49-·-介词加关系代词}&quot;">​</a></h2><ul><li>rely on — 依靠</li><li>live up to — 达到期望或标准</li></ul><p><strong>句型示范：</strong> The assistant on whom the household relied kept a careful record of every delivery.</p><p>on whom 引导限定从句，on 来自 rely on；从句修饰 assistant。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-049">进入本课</a></p><h2 id="lesson-50-·-动词后-ing-与-to-do-的意义" tabindex="-1">Lesson 50 · 动词后 ing 与 to do 的意义 <a class="header-anchor" href="#lesson-50-·-动词后-ing-与-to-do-的意义" aria-label="Permalink to &quot;Lesson 50 · 动词后 ing 与 to do 的意义 {#lesson-50-·-动词后-ing-与-to-do-的意义}&quot;">​</a></h2><ul><li>stick to — 坚持计划或规则</li><li>give up — 放弃，后接名词或动名词</li></ul><p><strong>句型示范：</strong> I stopped checking messages during study sessions and tried leaving my phone in another room.</p><p>stopped checking 是终止行为；tried leaving 是试用一个办法，而非宣称最终一定成功。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-050">进入本课</a></p><h2 id="lesson-51-·-将来完成时的截止视角" tabindex="-1">Lesson 51 · 将来完成时的截止视角 <a class="header-anchor" href="#lesson-51-·-将来完成时的截止视角" aria-label="Permalink to &quot;Lesson 51 · 将来完成时的截止视角 {#lesson-51-·-将来完成时的截止视角}&quot;">​</a></h2><ul><li>by the time — 到……的时候，注意后续时态</li><li>on the basis of — 根据某证据或假设</li></ul><p><strong>句型示范：</strong> If the schedule holds, the team will have tested all three models by Friday.</p><p>will have tested 以 Friday 为截止参照；if 从句使结果明确依赖进度条件。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-051">进入本课</a></p><h2 id="lesson-52-·-名词化与动作还原" tabindex="-1">Lesson 52 · 名词化与动作还原 <a class="header-anchor" href="#lesson-52-·-名词化与动作还原" aria-label="Permalink to &quot;Lesson 52 · 名词化与动作还原 {#lesson-52-·-名词化与动作还原}&quot;">​</a></h2><ul><li>in plain language — 用清楚朴素的语言</li><li>live up to — 达到宣传或期待</li></ul><p><strong>句型示范：</strong> The seller called the mixture a premium finish, but the label did not explain its ingredients.</p><p>called 加宾语和名词补语报告命名；but 后用具体缺失信息检验宣传，而非仅凭名称判断品质。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-052">进入本课</a></p><h2 id="lesson-53-·-形式主语与真正主语" tabindex="-1">Lesson 53 · 形式主语与真正主语 <a class="header-anchor" href="#lesson-53-·-形式主语与真正主语" aria-label="Permalink to &quot;Lesson 53 · 形式主语与真正主语 {#lesson-53-·-形式主语与真正主语}&quot;">​</a></h2><ul><li>in the public interest — 为了公共利益</li><li>hold accountable — 要求对行为负责</li></ul><p><strong>句型示范：</strong> It is essential that every complaint be recorded before the review begins.</p><p>it 为形式主语；that 从句为真正评价对象；be recorded 使用建议性原形虚拟式被动。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-053">进入本课</a></p><h2 id="lesson-54-·-whatever-与-no-matter-what" tabindex="-1">Lesson 54 · whatever 与 no matter what <a class="header-anchor" href="#lesson-54-·-whatever-与-no-matter-what" aria-label="Permalink to &quot;Lesson 54 · whatever 与 no matter what {#lesson-54-·-whatever-与-no-matter-what}&quot;">​</a></h2><ul><li>respond to — 对刺激或情况作出反应</li><li>by trial and error — 通过反复试错</li></ul><p><strong>句型示范：</strong> Whatever caused the bird to choose the red lid, one trial cannot establish a general rule.</p><p>whatever 从句作让步状语；主句独立成立，强调证据数量的限制。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-054">进入本课</a></p><h2 id="lesson-55-·-省略-if-的条件倒装" tabindex="-1">Lesson 55 · 省略 if 的条件倒装 <a class="header-anchor" href="#lesson-55-·-省略-if-的条件倒装" aria-label="Permalink to &quot;Lesson 55 · 省略 if 的条件倒装 {#lesson-55-·-省略-if-的条件倒装}&quot;">​</a></h2><ul><li>make sense of — 理解某信息</li><li>in principle — 原则上，不等于实际已实现</li></ul><p><strong>句型示范：</strong> Should anyone detect the signal, the repeated pattern may help them recognize it as intentional.</p><p>Should anyone detect 等于 If anyone should detect；may 保留识别成功的不确定性。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-055">进入本课</a></p><h2 id="lesson-56-·-混合时间条件句" tabindex="-1">Lesson 56 · 混合时间条件句 <a class="header-anchor" href="#lesson-56-·-混合时间条件句" aria-label="Permalink to &quot;Lesson 56 · 混合时间条件句 {#lesson-56-·-混合时间条件句}&quot;">​</a></h2><ul><li>rise above — 升到某水平之上</li><li>keep out — 阻挡进入</li></ul><p><strong>句型示范：</strong> If we had moved the supplies upstairs yesterday, they would be dry now.</p><p>had moved 指昨日未做的动作，would be dry now 表示当前反事实状态。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-056">进入本课</a></p><h2 id="lesson-57-·-as-if-与假设语气" tabindex="-1">Lesson 57 · as if 与假设语气 <a class="header-anchor" href="#lesson-57-·-as-if-与假设语气" aria-label="Permalink to &quot;Lesson 57 · as if 与假设语气 {#lesson-57-·-as-if-与假设语气}&quot;">​</a></h2><ul><li>bring back memories — 唤起回忆</li><li>no longer — 不再，说明过去与现在的变化</li></ul><p><strong>句型示范：</strong> The bakery smelled as if nothing had changed since my childhood.</p><p>as if 引出主观印象；had changed 以过去 smelled 为参照，since 标明持续范围。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-057">进入本课</a></p><h2 id="lesson-58-·-but-for-与-without-的隐含条件" tabindex="-1">Lesson 58 · but for 与 without 的隐含条件 <a class="header-anchor" href="#lesson-58-·-but-for-与-without-的隐含条件" aria-label="Permalink to &quot;Lesson 58 · but for 与 without 的隐含条件 {#lesson-58-·-but-for-与-without-的隐含条件}&quot;">​</a></h2><ul><li>clear up — 澄清或解决误会</li><li>but for — 要不是某因素，用于隐含条件</li></ul><p><strong>句型示范：</strong> But for the dated receipt, we would have been unable to explain the mix-up.</p><p>but for 引出过去反事实条件，would have been unable 描述过去本可能出现的结果。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-058">进入本课</a></p><h2 id="lesson-59-·-动名词作主语与宾语" tabindex="-1">Lesson 59 · 动名词作主语与宾语 <a class="header-anchor" href="#lesson-59-·-动名词作主语与宾语" aria-label="Permalink to &quot;Lesson 59 · 动名词作主语与宾语 {#lesson-59-·-动名词作主语与宾语}&quot;">​</a></h2><ul><li>take an interest in — 对某事产生兴趣</li><li>build up — 逐步积累</li></ul><p><strong>句型示范：</strong> Collecting old maps has taught me to notice how place names change.</p><p>Collecting old maps 整体作单数主语，谓语为 has taught；how 从句为 notice 的宾语。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-059">进入本课</a></p><h2 id="lesson-60-·-时间从句与将来表达整合" tabindex="-1">Lesson 60 · 时间从句与将来表达整合 <a class="header-anchor" href="#lesson-60-·-时间从句与将来表达整合" aria-label="Permalink to &quot;Lesson 60 · 时间从句与将来表达整合 {#lesson-60-·-时间从句与将来表达整合}&quot;">​</a></h2><ul><li>just as — 恰好在……时，也有比较用法，需看语境</li><li>ahead of time — 提前于安排时间</li></ul><p><strong>句型示范：</strong> Please call me when you arrive, and I will meet you at the side entrance.</p><p>when you arrive 是未来时间从句，用现在时；主句后半用 will 表示响应行动。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-060">进入本课</a></p>',63)])])}const g=n(l,[["render",i]]);export{u as __pageData,g as default};
